const mix = [
  [1, 20, 2],
  [2, 5, 1],
  [3, 5, 1],
];
export const questionCount = mix.reduce((sum, [, count]) => sum + count, 0);
export const totalPoints = mix.reduce((sum, [points, count]) => sum + points * count, 0);
export const passingPoints = Math.ceil(totalPoints * 0.8);

function shuffled(items, random) {
  const result = [...items];
  for (let end = result.length - 1; end > 0; end--) {
    const other = Math.floor(random() * (end + 1));
    [result[end], result[other]] = [result[other], result[end]];
  }
  return result;
}

export function makeAttempt(previous = [], random = Math.random) {
  const asked = new Set(previous.map(({ prompt }) => prompt));
  return mix.flatMap(([points, count, pictures]) => {
    const eligible = shuffled(
      questionBank.filter((item) => item.points === points),
      random,
    );
    const ranked = [
      ...eligible.filter((item) => !asked.has(item.prompt)),
      ...eligible.filter((item) => asked.has(item.prompt)),
    ];
    const chosen = shuffled(
      [
        ...ranked.filter((item) => item.picture).slice(0, pictures),
        ...ranked.filter((item) => !item.picture).slice(0, count - pictures),
      ],
      random,
    );
    return chosen.map((item) => {
      const order = shuffled(
        item.options.map((_, index) => index),
        random,
      );
      return {
        ...item,
        options: order.map((index) => item.options[index]),
        correct: item.correct.map((index) => order.indexOf(index)),
      };
    });
  });
}

export function gradeQuiz(questions, answers) {
  const items = questions.map((item, index) => {
    const selected = answers[index] ?? new Set();
    const earned =
      selected.size === item.correct.length && item.correct.every((choice) => selected.has(choice)) ? item.points : 0;
    return { ...item, selected, earned };
  });
  const score = items.reduce((sum, item) => sum + item.earned, 0);
  return { score, passed: score >= passingPoints, items };
}

// ---- ui.js ----

export function node(tag, className, text) {
  const element = document.createElement(tag);
  if (className) element.className = className;
  if (text != null) element.textContent = text;
  return element;
}

export function button(label, run, className = "wiki-button") {
  const action = node("button", className, label);
  action.type = "button";
  action.addEventListener("click", run);
  return action;
}

export function pageTitle(title, intro) {
  const heading = node("header", "wiki-page-title");
  const name = node("h1", null, title);
  name.tabIndex = -1;
  heading.append(name);
  if (intro) heading.append(node("p", "wiki-muted", intro));
  return heading;
}

// ---- exam.js ----

export function newExam() {
  return { questions: [], answers: [], index: 0, result: null, earned: false, message: "" };
}

function start(exam, render) {
  const questions = makeAttempt(exam.questions);
  Object.assign(exam, newExam(), { questions });
  render(true);
}

function isAnswered(exam, index) {
  return exam.answers[index]?.size === exam.questions[index].correct.length;
}

function submitExam(exam, { render, unlock }) {
  const missing = exam.questions.findIndex((_, index) => !isAnswered(exam, index));
  if (missing !== -1) {
    exam.index = missing;
    exam.message = "Complete this question before grading the quiz.";
    render(true);
    return;
  }
  const result = gradeQuiz(exam.questions, exam.answers);
  exam.result = result;
  render(true);
  if (result.passed) void unlock(result);
}

function quizFigure(entry, image, caption) {
  const illustration = node("figure", "wiki-exam-figure");
  illustration.append(image(entry, "wiki-detail-image"), node("figcaption", "wiki-muted", caption));
  return illustration;
}

function review(exam, open, image) {
  const rows = node("ol", "wiki-review");
  for (const item of exam.result.items) {
    const row = node("li");
    const toggle = node("details");
    const summary = node("summary");
    summary.append(node("span", null, item.prompt), node("span", "wiki-points", `${item.earned}/${item.points}`));
    const explanation = node("div", "wiki-explanation");
    const article = byId.get(item.article);
    const visual = byId.get(item.picture) ?? article;
    const selected = (indexes) =>
      [...indexes]
        .sort((a, b) => a - b)
        .map((index) => item.options[index])
        .join(" · ");
    explanation.append(
      node("p", null, `Your answer — ${selected(item.selected)}`),
      node("p", null, `Correct answer — ${selected(item.correct)}`),
      node("p", "wiki-muted", item.explanation),
    );
    if (visual.imageAlt) {
      const figure = quizFigure(visual, image, "AI-generated example of this print symptom.");
      figure.firstChild.loading = "lazy";
      explanation.append(figure, node("p", "wiki-muted", visual.check));
    }
    explanation.append(button(`Read ${article.title}`, () => open(article), "wiki-button wiki-chip"));
    toggle.append(summary, explanation);
    row.append(toggle);
    rows.append(row);
  }
  return rows;
}

export function showExam(exam, actions) {
  const { open, render, navigate, image } = actions;
  const page = node("section", "wiki-flow wiki-exam");
  if (!exam.questions.length) {
    const intro = node("div", "wiki-exam-card");
    intro.append(
      pageTitle(
        "FDM fundamentals quiz",
        "Practice choosing materials, reading print defects and preparing a part for the slicer.",
      ),
      node(
        "p",
        null,
        `Each attempt draws ${questionCount} questions from a bank of ${questionBank.length}, including four illustrated diagnosis questions. Questions are worth 1, 2 or 3 points. Multi-select questions require both correct choices.`,
      ),
      node("p", "wiki-muted", `Pass with at least ${passingPoints} of ${totalPoints} points (80%).`),
      button("Start quiz", () => start(exam, render), "wiki-button wiki-primary"),
    );
    page.append(intro);
    return page;
  }

  if (exam.result) {
    const { score, passed } = exam.result;
    const award = node("p", "wiki-award", exam.earned ? "Achievement earned · FDM Fundamentals" : "");
    award.dataset.wikiAward = "";
    award.setAttribute("aria-live", "polite");
    const controls = node("div", "wiki-actions");
    controls.append(
      button("Try a new set", () => start(exam, render), "wiki-button wiki-primary"),
      button("Browse guides", () => navigate("Guides")),
    );
    const result = node("div", "wiki-exam-card");
    result.append(
      pageTitle(
        passed ? "Quiz passed" : "Quiz complete",
        `${score} of ${totalPoints} points · ${Math.round((score / totalPoints) * 100)}%`,
      ),
      node(
        "p",
        "wiki-muted",
        passed
          ? "You reached the 80% pass mark."
          : `The pass mark is ${passingPoints} points. Review your answers below before trying another set.`,
      ),
      award,
      controls,
    );
    page.append(result, node("h2", null, "Review answers"), review(exam, open, image));
    return page;
  }

  const { index } = exam;
  const item = exam.questions[index];
  const multiple = item.correct.length > 1;
  const selected = exam.answers[index] ?? new Set();
  const panel = node("div", "wiki-exam-card");
  const meta = node("div", "wiki-question-status");
  const progress = node("progress", "wiki-progress");
  progress.max = questionCount;
  progress.setAttribute("aria-label", "Questions answered");
  const progressText = node("span", "wiki-muted");
  function updateProgress() {
    const count = exam.questions.filter((_, questionIndex) => isAnswered(exam, questionIndex)).length;
    progress.value = count;
    progressText.textContent = `${count} of ${questionCount} answered`;
  }
  updateProgress();
  meta.append(progressText, node("span", "wiki-points", `${item.points} ${item.points === 1 ? "point" : "points"}`));
  panel.append(pageTitle(`Question ${index + 1} of ${questionCount}`), meta, progress);
  const options = node("fieldset", "wiki-options");
  options.append(node("legend", null, item.prompt));
  if (item.picture) options.append(quizFigure(byId.get(item.picture), image, "AI-generated practice image."));
  options.append(node("p", "wiki-muted", multiple ? `Select ${item.correct.length} answers.` : "Select one answer."));
  item.options.forEach((answer, choice) => {
    const row = node("label", "wiki-option");
    const input = node("input");
    input.type = multiple ? "checkbox" : "radio";
    input.name = "wiki-answer";
    input.checked = selected.has(choice);
    input.addEventListener("change", () => {
      if (multiple) {
        if (input.checked) selected.add(choice);
        else selected.delete(choice);
        exam.answers[index] = selected;
      } else exam.answers[index] = new Set([choice]);
      updateProgress();
    });
    row.append(input, node("span", null, answer));
    options.append(row);
  });

  function goTo(next) {
    exam.index = next;
    exam.message = "";
    render(true);
  }

  const controls = node("div", "wiki-exam-controls");
  const previous = button("← Previous", () => goTo(index - 1));
  previous.disabled = index === 0;
  controls.append(previous);
  if (index < questionCount - 1 && !exam.message) {
    controls.append(button("Next →", () => goTo(index + 1), "wiki-button wiki-primary"));
  } else {
    controls.append(button("Grade quiz", () => submitExam(exam, actions), "wiki-button wiki-primary"));
  }
  panel.append(options);
  if (exam.message) {
    const warning = node("p", "wiki-notice", exam.message);
    warning.setAttribute("role", "alert");
    panel.append(warning);
  }
  panel.append(controls);
  page.append(panel);
  return page;
}

// ---- window.js ----

const defectImages = {
  "wet-filament": "data:image/webp;base64,",
  "layer-shift": "data:image/webp;base64,",
  "ringing": "data:image/webp;base64,",
  "layer-separation": "data:image/webp;base64,",
  "seam-blobs": "data:image/webp;base64,",
  "spaghetti": "data:image/webp;base64,",
  "poor-bridging": "data:image/webp;base64,",
  "rough-supports": "data:image/webp;base64,",
  "small-layer-overheating": "data:image/webp;base64,",
  "top-gaps": "data:image/webp;base64,",
  "infill-wall-gap": "data:image/webp;base64,"
};

const shelves = new Map([
  ["Guides", { intro: "Choose a workflow, set up the slicer and make parts easier to print.", entries: guides }],
  [
    "Troubleshooting",
    {
      intro:
        "Start with what you can see, hear or measure. Each case includes a diagnostic check and a way to verify the fix.",
    },
  ],
  [
    "Materials",
    {
      intro: "Choose by use, then start with the filament maker’s printer and plate recommendations.",
      entries: materials,
    },
  ],
  [
    "Printers",
    {
      intro: "Explore familiar makers and models, and compare the choices that affect what you can print.",
      entries: printers,
    },
  ],
  ["History", { intro: "Explore the people, machines, files and habits that shaped FDM printing.", entries: history }],
  ["Glossary", { intro: "Filament printing terms from anisotropy to Z offset.", entries: terms }],
]);

function picture(entry, className, src) {
  const img = node("img", className);
  img.src = src;
  img.alt = entry.imageAlt;
  img.width = 420;
  img.height = 420;
  img.decoding = "async";
  return img;
}

function entryGrid(entries, open, layout = "", image) {
  const grid = node("div", ["wiki-grid", layout].filter(Boolean).join(" "));
  for (const entry of entries) {
    const card = button("", () => open(entry), "wiki-card");
    if (entry.imageAlt && image) {
      const img = image(entry, layout === "wiki-photos" ? "wiki-card-photo" : "wiki-card-thumb");
      img.loading = "lazy";
      card.append(img);
    }
    const content = node("span", "wiki-card-content");
    const title = node("span", "wiki-card-title", entry.title);
    if (layout === "wiki-results") content.append(node("span", "wiki-category", entry.section));
    content.append(title, node("span", "wiki-muted", entry.summary));
    card.append(content, node("span", "wiki-card-arrow", "↗"));
    card.lastChild.setAttribute("aria-hidden", "true");
    grid.append(card);
  }
  return grid;
}

function overview(open, navigate, image) {
  const section = node("div", "wiki-flow");
  const hero = node("section", "wiki-hero");
  const copy = pageTitle(
    "3D printing, from model to part",
    "A practical wiki for FDM filament printing. Set up your next print, choose a material or diagnose a defect.",
  );
  const actions = node("div", "wiki-actions");
  actions.append(
    button("Find a print defect", () => navigate("Troubleshooting"), "wiki-button wiki-primary"),
    button("Read the first-print guide", () => open(byId.get("first-print")), "wiki-button wiki-hero-secondary"),
  );
  copy.append(actions);
  hero.append(copy, image(byId.get("stringing"), "wiki-hero-image"));
  const common = node("section", "wiki-flow");
  common.append(
    node("h2", null, "Common print defects"),
    entryGrid(
      ["first-layer", "warping", "layer-shift"].map((id) => byId.get(id)),
      open,
      "wiki-photos",
      image,
    ),
  );
  const workflow = node("section", "wiki-flow");
  workflow.append(
    node("h2", null, "Prepare a print"),
    entryGrid(
      ["slicers", "cut-prints", "bridging-guide", "cad"].map((id) => byId.get(id)),
      open,
    ),
  );
  const practical = node("section", "wiki-flow");
  practical.append(
    node("h2", null, "Choose settings for your next print"),
    entryGrid(
      ["layer-height", "filament-drying", "shell-settings", "nozzle-guide"].map((id) => byId.get(id)),
      open,
    ),
  );
  const background = node("section", "wiki-flow");
  background.append(
    node("h2", null, "Printers and their history"),
    entryGrid([byId.get("printer-types"), byId.get("reprap-history"), byId.get("benchy-history")], open),
  );
  section.append(hero, practical, common, workflow, background);
  return section;
}

function troubleshooting(selected, select, open, image) {
  const page = node("section", "wiki-flow");
  const filters = node("div", "wiki-actions");
  filters.setAttribute("role", "group");
  filters.setAttribute("aria-label", "Filter by symptom");
  const labels = ["All cases", ...issueGroups.map(({ title }) => title)];
  for (const [index, label] of labels.entries()) {
    const filter = button(label, () => select(index), "wiki-button wiki-filter");
    filter.setAttribute("aria-pressed", String(index === selected));
    filters.append(filter);
  }
  page.append(pageTitle("Troubleshooting", shelves.get("Troubleshooting").intro), filters);
  for (const [index, { title, entries }] of issueGroups.entries()) {
    if (selected && selected !== index + 1) continue;
    const group = node("section", "wiki-flow");
    group.append(node("h2", null, title), entryGrid(entries, open, "wiki-case-grid", image));
    page.append(group);
  }
  return page;
}

function articleBlock(title, content) {
  if (typeof content === "string") return node("p", null, content);
  const block = node("div", "wiki-flow wiki-table-block");
  if (content.text) block.append(node("p", null, content.text));
  const scroll = node("div", "wiki-table-scroll");
  scroll.tabIndex = 0;
  scroll.setAttribute("role", "region");
  scroll.setAttribute("aria-label", title);
  const table = node("table", "wiki-table");
  table.setAttribute("aria-label", title);
  const head = table.createTHead().insertRow();
  for (const name of content.columns) {
    const label = node("th", null, name);
    label.scope = "col";
    head.append(label);
  }
  const rows = table.createTBody();
  for (const row of content.rows) {
    const tr = rows.insertRow();
    for (const value of row) tr.insertCell().textContent = value;
  }
  scroll.append(table);
  block.append(scroll);
  if (content.note) block.append(node("p", "wiki-muted", content.note));
  return block;
}

function detail(entry, open, back, image) {
  const page = node("article", "wiki-flow");
  const heading = pageTitle(entry.title, entry.summary);
  const section = entry.category ? `${entry.section} / ${entry.category}` : entry.section;
  heading.prepend(button("← Back", back, "wiki-button wiki-back"), node("p", "wiki-category", section));
  page.append(heading);

  const body = node("div", entry.imageAlt ? "wiki-detail wiki-has-photo" : "wiki-detail");
  const text = node("div", "wiki-article-copy wiki-flow");

  function addBlock(title, content) {
    const block = node("section");
    block.append(node("h2", null, title), content);
    text.append(block);
  }

  if (entry.fixes) {
    addBlock("How to tell", node("p", null, entry.check));
    addBlock("Why it happens", node("p", null, entry.causes));
    const list = node("ol", "wiki-steps");
    for (const step of entry.fixes) list.append(node("li", null, step));
    addBlock("What to try", list);
    addBlock("Confirm the fix", node("p", null, entry.verify));
  }
  if (entry.uses) {
    addBlock("Where to use it", node("p", null, entry.uses));
    addBlock("How to print it", node("p", null, entry.setup));
    addBlock("Trade-offs", node("p", null, entry.limits));
  }
  for (const [title, description] of entry.blocks ?? []) addBlock(title, articleBlock(title, description));
  body.append(text);

  if (entry.imageAlt) {
    const figure = node("figure", "wiki-figure");
    figure.append(
      image(entry, "wiki-detail-image"),
      node("figcaption", "wiki-muted", "AI-generated example of this print defect."),
    );
    body.prepend(figure);
  }
  if (text.childElementCount) page.append(body);

  if (entry.related.length) {
    const related = node("section", "wiki-flow");
    const links = node("div", "wiki-actions");
    for (const id of entry.related) {
      const target = byId.get(id);
      links.append(button(target.title, () => open(target), "wiki-button wiki-chip"));
    }
    related.append(node("h2", null, "Related reading"), links);
    page.append(related);
  }

  const sources = entry.sources ?? (entry.source ? [["Read the source guide", entry.source]] : []);
  if (sources.length) {
    const references = node("section", "wiki-flow wiki-references");
    const list = node("ul");
    for (const [name, url] of sources) {
      const link = node("a", null, name);
      link.href = url;
      link.target = "_blank";
      link.rel = "noopener noreferrer";
      const row = node("li");
      row.append(link);
      list.append(row);
    }
    references.append(node("h2", null, "References"), list);
    page.append(references);
  }
  return page;
}

export default function mount(thingport) {
  const { root } = thingport;
  const input = root.querySelector("[data-wiki-search]");
  const clear = root.querySelector("[data-wiki-clear]");
  const status = root.querySelector("[data-wiki-status]");
  const nav = root.querySelector("[data-wiki-nav]");
  const pane = root.querySelector("[data-wiki-pane]");
  if (!input || !clear || !status || !nav || !pane) return;
  const template = root.querySelector("[data-wiki-images]");
  const markupImages = new Map(
    Array.from(template?.content.querySelectorAll("img") ?? [], (img) => [img.dataset.case, img.getAttribute("src")]),
  );
  const image = (entry, className) => picture(entry, className, defectImages[entry.id] ?? markupImages.get(entry.id));

  const activity = new AbortController();
  const { signal } = activity;
  const exam = newExam();
  const history = [];
  let shelf = "Overview";
  let entry = null;
  let query = "";
  let issueGroup = 0;

  const navigation = new Map(
    ["Overview", ...shelves.keys(), "Quiz"].map((name) => [name, button(name, () => navigate(name), "wiki-tab")]),
  );
  nav.append(...navigation.values());

  function navigate(name) {
    shelf = name;
    entry = null;
    history.length = 0;
    updateQuery("");
    render(true);
  }

  function open(target) {
    history.push({ entry, query });
    entry = target;
    updateQuery("");
    render(true);
  }

  function back() {
    const previous = history.pop();
    entry = previous?.entry ?? null;
    updateQuery(previous?.query ?? "");
    render(true);
  }

  function updateQuery(value) {
    input.value = value;
    query = value.trim();
    clear.hidden = !value;
  }

  function selectIssueGroup(group) {
    issueGroup = group;
    render();
    pane.querySelector(".wiki-filter[aria-pressed='true']")?.focus({ preventScroll: true });
  }

  function render(focus = false) {
    root.scrollTop = 0;
    const current = query ? "" : (entry?.section ?? shelf);
    for (const [name, link] of navigation) {
      if (name === current) link.setAttribute("aria-current", "page");
      else link.removeAttribute("aria-current");
    }
    let display;
    if (query) {
      const results = searchWiki(query);
      const count = results.length;
      const label = count ? `${count} ${count === 1 ? "result" : "results"}` : "No results";
      status.textContent = label;
      display = node("section", "wiki-flow");
      display.append(
        pageTitle("Search results", `${label} for “${query}”`),
        count
          ? entryGrid(results, open, "wiki-results")
          : node("p", "wiki-empty", "Try a material, a symptom or a shorter term, such as PETG, layer shift or brim."),
      );
    } else {
      status.textContent = "";
      if (entry) display = detail(entry, open, back, image);
      else if (shelf === "Overview") display = overview(open, navigate, image);
      else if (shelf === "Quiz") display = showExam(exam, { open, render, unlock, navigate, image });
      else if (shelf === "Troubleshooting") display = troubleshooting(issueGroup, selectIssueGroup, open, image);
      else {
        const { intro, entries } = shelves.get(shelf);
        display = node("section", "wiki-flow");
        display.append(pageTitle(shelf, intro), entryGrid(entries, open));
      }
    }
    pane.replaceChildren(display);
    if (focus) pane.querySelector("h1")?.focus({ preventScroll: true });
  }

  async function unlock(result) {
    const earned = await thingport.achievements?.unlock("fundamentals");
    if (earned && !signal.aborted && exam.result === result) {
      exam.earned = true;
      if (shelf === "Quiz" && !entry && !query) {
        const award = pane.querySelector("[data-wiki-award]");
        if (award) award.textContent = "Achievement earned · FDM Fundamentals";
      }
    }
  }

  input.addEventListener(
    "input",
    () => {
      updateQuery(input.value);
      render();
    },
    { signal },
  );
  input.addEventListener(
    "keydown",
    (event) => {
      if (event.key === "Escape" && input.value) {
        event.preventDefault();
        event.stopPropagation();
        clearSearch();
      }
      if (event.key === "Enter" && query) {
        event.preventDefault();
        pane.querySelector("h1")?.focus();
      }
    },
    { signal },
  );
  clear.addEventListener("click", clearSearch, { signal });

  function clearSearch() {
    updateQuery("");
    render();
    input.focus();
  }

  render();
  return () => activity.abort();
}
